<script setup lang="ts">import {ref,onMounted,computed,watch} from 'vue';import {useRoute} from 'vue-router';import {useResearch} from '../stores/research';import {useTask} from '../hooks/useTask';import {usePolling} from '../hooks/usePolling';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import EmptyState from '../components/common/EmptyState.vue';import SegmentSummary from '../components/SegmentSummary.vue';import ClusterPlot from '../components/ClusterPlot.vue';import {number} from '../utils/format';const route=useRoute(),store=useResearch(),selected=ref(Number(route.query.run)||0),{error,perform}=useTask();const run=computed(()=>store.runs.find(r=>r.id===selected.value)),segments=computed(()=>store.segments.filter(s=>s.run_id===selected.value));onMounted(()=>perform(async()=>{await store.load();if(!selected.value)selected.value=store.runs.find(r=>r.status==='completed')?.id||0;}));watch(()=>route.query.run,v=>{if(v)selected.value=Number(v);});usePolling(async()=>{if(run.value&&['queued','running'].includes(run.value.status))await store.load();});</script><template><PageHeading eyebrow="INTERPRET / FROM DISTANCE TO CONTEXT" title="把群组读成业务线索" description="中心值已经还原为原始量纲。用特征解释差异，再决定如何行动。"><RouterLink class="outline" to="/campaigns">制定触达方案 ↗</RouterLink></PageHeading><ErrorNotice :message="error" @retry="perform(store.load)"/><div class="run-picker"><label>研究档案<select v-model="selected"><option v-for="r in store.runs" :value="r.id" :key="r.id">#{{r.id}} {{r.name}}</option></select></label><StatusBadge v-if="run" :status="run.status"/></div><template v-if="run?.status==='completed'"><div class="result-layout"><ClusterPlot :run="run"/><section class="model-comparison"><p class="eyebrow">MODEL SELECTION</p><h2>K = {{run.result.best_k}} <small>本次建议</small></h2><div v-for="c in run.result.candidates||[]" :key="c.k" class="score-row" :class="{chosen:c.k===run.result.best_k}"><span>K {{c.k}}</span><div><i :style="{width:Math.max(0,c.silhouette)*100+'%'}"></i></div><b>{{number(c.silhouette,3)}}</b></div><p>{{run.result.sample_count}} 位客户 · seed {{run.result.seed}}</p></section></div><div class="section-title"><h2>群组解释 <small>同一研究内，互不重叠的人群</small></h2></div><div class="segment-grid"><SegmentSummary v-for="s in segments" :key="s.id" :segment="s"><RouterLink :to="'/campaigns?segment='+s.id">以此群组建立方案 →</RouterLink></SegmentSummary></div><p class="checksum">复算指纹 SHA256 / {{run.result.checksum}}</p></template><EmptyState v-else :title="run?.status==='failed'?'本次计算未完成':'研究正在等待结果'" :text="run?.error||'队列状态会自动刷新。尚未建立研究时，请前往分群实验，选择至少两个特征。'"/></template>
